import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../gopal-krishna-gokhale-explorer",e),"utf-8")}function readHubData(){return readFileSync(resolve(__dirname,"../../freedom-fighters-hub/script.js"),"utf-8")}describe("Gopal Krishna Gokhale Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(e).toContain('class="gokhale-hero"'),expect(e).toContain("<h1>"),expect(e).toContain("Gopal Krishna"),expect(e).toContain("Gokhale"),expect(e).toContain("Political Guru")}),it("contains all required content sections from the issue",()=>{["biography","timeline","congress","social-reforms","references"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("highlights his moderate approach, social reforms, and influence on Gandhi",()=>{expect(e).toContain("moderate"),expect(e).toContain("Servants of India Society"),expect(e).toContain("social reform"),expect(e).toContain("Indian National Congress"),expect(e).toContain("Gandhi")}),it("has a semantic heading hierarchy (single h1, multiple h2s)",()=>{const t=(e.match(/<h1[\s>]/g)||[]).length,a=(e.match(/<h2[\s>]/g)||[]).length;expect(t).toBe(1),expect(a).toBeGreaterThanOrEqual(6)}),it("uses HTTPS image sources with alt attributes",()=>{const t=e.match(/<img [^>]*>/g)||[];expect(t.length).toBeGreaterThanOrEqual(4),t.forEach(e=>{expect(e).toMatch(/src="https:\/\//),expect(e).toMatch(/alt="/),expect(e).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')}),it("references authentic source documentation in References",()=>{expect(e).toContain("wikipedia.org"),expect(e).toContain("britannica.com"),expect(e).toContain("india.gov.in")})}),describe("Gopal Krishna Gokhale Explorer — Assets",()=>{it("includes a non-empty stylesheet themed for the moderate era",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain("gokhale-hero")}),it("includes a valid interactive script with required functions",()=>{const e=readExplorerFile("script.js");expect(e).toContain("activateTab"),expect(e).toContain("initTabNavigation"),expect(e).toContain("initThemeToggle"),expect(e).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Gopal Krishna Gokhale — Landing Page Integration",()=>{it("is listed as a card on the Freedom Fighters Hub landing page",()=>{const e=readHubData();expect(e).toContain("gokhale"),expect(e).toContain("Gopal Krishna Gokhale")}),it("includes the moderate-era metadata and a dedicated explorer link",()=>{const e=readHubData();expect(e).toContain("Political Guru of Gandhi"),expect(e).toContain("Early Nationalist"),expect(e).toContain("Social Reforms"),expect(e).toContain("../gopal-krishna-gokhale-explorer/index.html")})});